#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct Sites;

impl ::sittir_core::options::OptionSites for Sites {
    const TABLES: ::sittir_core::options::OptionTables = ::sittir_core::options::OptionTables {
        addresses: ADDRESSES,
        allowed,
        delimiter_allowed,
        depth_sites: DEPTH_SITES,
        indent: INDENT_KIND,
        dedent: DEDENT_KIND,
        indent_chars: " \t",
    };
}

pub type Options = ::sittir_core::options::Options<Sites>;

#[cfg(test)]
mod resolve_tests {
    use super::*;

    fn resolve(json: &str) -> Result<ResolvedOptions, String> {
        let ::serde_json::Value::Object(obj) = ::serde_json::from_str(json).unwrap() else { unreachable!() };
        Options::read(&obj)?.resolve(&defaults())
    }

    #[test]
    fn no_options_leaves_the_defaults() {
        assert_eq!(resolve("{}"), Ok(defaults()));
    }

    #[test]
    fn an_unknown_key_is_refused() {
        assert_eq!(resolve(r#"{"no_such_address":1}"#), Err("options: unknown key no_such_address".to_string()));
    }

    #[test]
    fn an_unknown_key_beneath_a_branch_names_the_branch() {
        assert_eq!(resolve("{\"abstractClassDeclaration\":{\"no_such_address\":1}}"), Err("options: (abstract_class_declaration)/no_such_address names no site".to_string()));
    }

    #[test]
    fn a_differing_admitted_value_changes_only_its_own_sites() {
        let table = resolve("{\"abstractClassDeclaration\":{\"abstractKeyword\":{\"after\":180}}}").unwrap();
        let expected = defaults();
        let named = [SITE_ABSTRACT_CLASS_DECLARATION_ABSTRACT_KEYWORD_AFTER];
        for i in 0..table.spacing.len() {
            assert_eq!(table.spacing[i].arm, if named.contains(&i) { 180 } else { expected.spacing[i].arm });
        }
        assert_eq!(table.delimiter, expected.delimiter);
        assert_eq!(table.indent, expected.indent);
    }

    #[test]
    fn a_value_the_site_does_not_admit_is_refused_with_its_path() {
        assert_eq!(resolve("{\"abstractClassDeclaration\":{\"abstractKeyword\":{\"after\":65534}}}"), Err("options: (abstract_class_declaration)/\"abstract\"/after does not admit kind id 65534 (allowed: [180, 181, 182, 183, 184, 185, 186, 187])".to_string()));
    }

    #[test]
    fn an_unbalanced_indent_is_refused() {
        assert_eq!(resolve("{\"abstractClassDeclaration\":{\"abstractKeyword\":{\"after\":186}}}"), Err("options: abstract_class_declaration opens an indent it never dedents".to_string()));
    }
}
